INSERT INTO signal (id, signal_type, title, description, impact, severity, risk_bucket, recommended_action, sources, detected_at, trend, related_segment, metrics, confidence_score, confidence_rationale, confidence_signals_used, confidence_threshold, model_version, validated_at, escalation_triggered, escalation_reason, escalation_route_to) VALUES ('SIG-ARAMCO-SUP-001', 'expired_permit_live_occupancy', 'Two Expired Hot-Work Permits — Seven People Still On Location', 'HW-4471 expired 47 min ago (4 workers) and HW-4468 expired 35 min ago (3 workers). Both groups remain active inside Unit 2 hazard zone.', 'high', 'critical', 'safety', 'Extend with documented fresh conditions, or stop the work and confirm the zone is clear.', '["Permit-to-Work System (electronic)", "Location tracking system"]', '2026-08-05T02:47:00-04:00', 'worsening', 'UNIT-2-HOTWORK', '{"workers": 7, "expiredPermits": 2, "minutesPastExpiry": [47, 35]}', 96, 'Permit expiry confirmed from PTW system; worker presence confirmed from two independent location feeds.', '["Permit-to-Work System (electronic)", "Location tracking system", "Gate access-control"]', 70, 'hse-permit-breach-v1.0', '2026-08-05T02:47:00-04:00', TRUE, 'Live occupancy inside a hazard zone on a lapsed hot-work permit', 'Unit 2 shift supervisor and permit issuer');
INSERT INTO signal (id, signal_type, title, description, impact, severity, risk_bucket, recommended_action, sources, detected_at, trend, related_segment, metrics, confidence_score, confidence_rationale, confidence_signals_used, confidence_threshold, model_version, validated_at, escalation_triggered, escalation_reason, escalation_route_to) VALUES ('SIG-ARAMCO-SUP-002', 'gas_test_overdue', 'Confined-Space Gas Test Due in Less Than One Minute — CS-1182', 'CS-1182 last gas test was 14 minutes ago. With a 15-minute interval, the next test is due in approximately 1 minute.', 'high', 'warning', 'safety', 'Standby attendant to conduct gas test immediately and log result.', '["Permit-to-Work System (electronic)", "Gas detection system"]', '2026-08-05T02:53:00-04:00', 'worsening', 'UNIT-3-CS', '{"permitId": "CS-1182", "dueInMinutes": 1, "intervalMinutes": 15, "lastTestMinutesAgo": 14}', 95, 'Gas test timer derived from permit condition log with high reliability.', '["Permit-to-Work System (electronic)", "Gas detection system"]', 70, 'hse-permit-breach-v1.0', '2026-08-05T02:53:00-04:00', TRUE, 'Confined-space gas test interval approaching breach', 'Unit 3 permit issuer and standby attendant');
INSERT INTO signal (id, signal_type, title, description, impact, severity, risk_bucket, recommended_action, sources, detected_at, trend, related_segment, metrics, confidence_score, confidence_rationale, confidence_signals_used, confidence_threshold, model_version, validated_at, escalation_triggered, escalation_reason, escalation_route_to) VALUES ('SIG-ARAMCO-SUP-003', 'asset_alarm_permit_overlap', 'Degraded Compressor C-2101 — Six Permits Within Exclusion Radius', 'AST-C2101 health score 62/100 with vibration in alarm state. Six open permits including two hot-work are within the compressor exclusion radius.', 'medium', 'warning', 'equipment', 'Review permits within C-2101 exclusion radius; assess whether hot-work permits should be suspended pending bearing inspection.', '["Condition-monitoring system", "Permit-to-Work System (electronic)"]', '2026-08-05T02:45:00-04:00', 'worsening', 'UNIT-2-ASSET', '{"assetId": "AST-C2101", "healthScore": 62, "linkedPermits": 6, "linkedHighRiskPermits": 2}', 82, 'Asset health from condition-monitoring system; permit count from PTW system spatial join.', '["Condition-monitoring system", "Permit-to-Work System (electronic)"]', 70, 'hse-permit-breach-v1.0', '2026-08-05T02:45:00-04:00', FALSE, NULL, NULL);
